import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

const Navbar = () => {
    const { user, googleSignIn, logOut } = useAuth();
    const [cartCount, setCartCount] = useState(0);

    // Sync cart count every time the component renders or storage updates
    useEffect(() => {
        const updateCount = () => {
            const cart = JSON.parse(localStorage.getItem('bindass_cart')) || [];
            setCartCount(cart.length);
        };
        updateCount();
        window.addEventListener('storage', updateCount); // Listen for changes across tabs
        return () => window.removeEventListener('storage', updateCount);
    }, []);

    return (
        <header className="sticky top-0 z-50 bg-[#10221c] text-white font-['Manrope']">
            <div className="max-w-[1440px] mx-auto px-6 h-16 flex items-center justify-between">
                {/* Logo */}
                <Link to="/" className="flex items-center gap-2">
                    <div className="w-8 h-5 bg-white rounded-[2px] flex items-center justify-center">
                        <span className="material-icons-outlined text-[#10221c] text-sm">architecture</span>
                    </div>
                    <span className="text-xl font-extrabold tracking-tighter uppercase">BINDASS!!</span>
                </Link>

                {/* Search */}
                <div className="flex-1 max-w-xl mx-8 hidden lg:block">
                    <div className="relative">
                        <span className="material-icons-outlined absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">search</span>
                        <input type="text" placeholder="Find a piece" className="w-full bg-white text-slate-900 rounded-full py-2 pl-12 pr-4 text-xs focus:outline-none" />
                    </div>
                </div>

                {/* Actions */}
                <div className="flex items-center space-x-6">
                    {user ? (
                        <Link to="/profile" className="flex items-center gap-2">
                            <img src={user.photoURL} className="w-8 h-8 rounded-full border border-white/20" alt="pfp" />
                            <span className="text-[10px] font-bold uppercase hidden md:block">{user.displayName.split(' ')[0]}</span>
                        </Link>
                    ) : (
                        <button onClick={googleSignIn} className="material-icons-outlined hover:text-emerald-400">person_outline</button>
                    )}

                    <Link to="/cart" className="relative hover:text-emerald-400 transition-colors">
                        <span className="material-icons-outlined">shopping_bag</span>
                        {cartCount > 0 && (
                            <span className="absolute -top-1 -right-1 bg-white text-[#10221c] text-[9px] w-4 h-4 flex items-center justify-center rounded-full font-bold">
                                {cartCount}
                            </span>
                        )}
                    </Link>
                </div>
            </div>
        </header>
    );
};

export default Navbar;
